quad:
#version 300 es
precision highp float;
out vec2 uv;
void main() {
    vec2 q = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
    uv = q;
    gl_Position = vec4(q * 2.0 - 1.0, 0.0, 1.0);
}

sprite_vertex:
#version 300 es
precision highp float;
uniform vec4 rect;
uniform vec2 viewport;
out vec2 uv;
void main() {
    vec2 q = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
    uv = q;
    vec2 pixel = rect.xy + q * rect.zw;
    gl_Position = vec4(pixel.x / viewport.x * 2.0 - 1.0,
                       1.0 - pixel.y / viewport.y * 2.0, 0.0, 1.0);
}

sprite:
#version 300 es
precision highp float;
uniform sampler2D image;
uniform float gain;
uniform vec3 tint;
uniform int kind;
in vec2 uv;
out vec4 color;
void main() {
    if (any(lessThan(uv, vec2(0))) || any(greaterThan(uv, vec2(1)))) discard;
    vec4 texel = texture(image, uv);
    if (kind == 1) color = vec4(tint * texel.a * gain, texel.a * gain);
    else if (kind == 2) color = vec4(texel.rgb * texel.a, texel.a);
    else color = texel;
}

eye:
#version 300 es
precision highp float;
uniform sampler2D artwork;
uniform sampler2D distance_field;
uniform vec2 patch_size;
uniform vec2 eye_size;
uniform vec4 shape; // lid, slant, smile, outer side
uniform vec4 deform; // width, height, openness, tilt
uniform vec2 light; // luminance, glint
in vec2 uv;
out vec4 color;
float tapered_segment(vec2 p,vec2 a,vec2 b,float ra,float rb) {
    vec2 ab=b-a;
    float u=clamp(dot(p-a,ab)/dot(ab,ab),0.0,1.0);
    return mix(ra,rb,u)-length(p-mix(a,b,u));
}
void main() {
    vec2 p = (uv - 0.5) * patch_size;
    float angle = deform.w * shape.w;
    float c = cos(angle), s = sin(angle);
    p = vec2(c*p.x + s*p.y, -s*p.x + c*p.y);
    vec2 rotated = p;
    p /= vec2(deform.x * (1.0 + (1.0-deform.z)*0.055), max(0.025, deform.y*deform.z));
    vec2 q = p / eye_size + 0.5;
    bool outside = any(lessThan(q, vec2(0))) || any(greaterThan(q, vec2(1)));
    float x = q.x*2.0-1.0;
    // Tiny lid values should not shave a flat plateau off the rounded forehead.
    // Larger expressions retain a clear slant with a softly curved eyelid.
    float upper = max(0.0, (shape.x-0.07)/0.93);
    float top = upper*(0.82+0.18*x*x) + shape.y*x*shape.w*0.5;
    float bottom = 1.0-shape.z*sqrt(max(0.0, 1.0-pow(x*0.91, 2.0)));
    bottom=max(bottom,top+0.18); // keep combined upper/lower lids from pinching apart
    float aa = max(fwidth(q.y), 0.0005);
    float lid = smoothstep(top-aa, top+aa, q.y) * (1.0-smoothstep(bottom-aa,bottom+aa,q.y));
    vec4 texel = texture(artwork, q);
    float matte = outside ? 0.0 : texel.a * lid;
    float closure = 1.0-smoothstep(0.12,0.65,deform.z);
    if (closure > 0.0) {
        float scale_y = max(0.025,deform.y*deform.z);
        float open_distance = outside ? -24.5 : min((texture(distance_field,q).r*49.0-24.5),
                                      min(q.y-top,bottom-q.y)*eye_size.y);
        // Replace the projecting lash as one connected curve, instead of leaving
        // an isolated remnant of the original texture during the morph.
        open_distance=min(open_distance,(0.5+shape.w*(q.x-0.5)-0.14)*eye_size.x);
        open_distance=max(-24.5,open_distance);
        open_distance *= scale_y;
        float span = eye_size.x*0.36*deform.x;
        float aperture_center=(upper*0.82-shape.z)*0.5*eye_size.y*scale_y;
        vec2 local = rotated-vec2(eye_size.x*0.035*shape.w,aperture_center);
        float nearest_x = clamp(local.x,-span,span);
        float curve = mix(-0.055,0.095,clamp(shape.z/0.61,0.0,1.0))*eye_size.y*(0.35+closure*0.65);
        float nearest_y = curve*pow(nearest_x/span,2.0);
        float thickness = max(1.8,eye_size.y*0.016);
        float stroke_distance = thickness-length(local-vec2(nearest_x,nearest_y));
        // Somnia's outer flick is an eyelash, not an expendable artifact.
        // Carry it into the closed lid as an attached, softly tapered curve.
        vec2 lash_root=vec2(-shape.w*span*0.8,curve*0.64);
        vec2 lash_control=lash_root+vec2(-shape.w*eye_size.x*0.13,eye_size.y*0.010);
        vec2 lash_tip=lash_root+vec2(-shape.w*eye_size.x*0.17,-eye_size.y*0.065);
        vec2 previous=lash_root;
        float lash_distance=-1000.0;
        for(int i=1;i<=4;i++) {
            float u=float(i)/4.0;
            vec2 next=mix(mix(lash_root,lash_control,u),mix(lash_control,lash_tip,u),u);
            float lash=tapered_segment(local,previous,next,
                        thickness*mix(0.92,0.35,float(i-1)/4.0),thickness*mix(0.92,0.35,u));
            lash_distance=max(lash_distance,lash);
            previous=next;
        }
        float distance = mix(open_distance,stroke_distance,closure);
        distance=max(distance,lash_distance);
        float rounded = smoothstep(-0.8,0.8,distance);
        matte = mix(matte,rounded,smoothstep(0.0,0.10,closure));
        vec2 color_uv = vec2(clamp(rotated.x/eye_size.x+0.5,0.2,0.8),0.42);
        // Newly drawn eyelash pixels have no source-texture color. Fill them
        // from the eye's color field instead of blending in transparent black.
        texel.rgb = mix(texel.rgb,texture(artwork,color_uv).rgb,max(closure,1.0-texel.a));
    }
    float alpha = matte * min(1.0, max(0.35, light.x));
    vec2 glint = (q-vec2(0.5-0.14*shape.w, 0.30))*eye_size;
    float radius = eye_size.x*0.046*light.y;
    float star = 1.0-smoothstep(radius, radius+1.2, abs(glint.x)+abs(glint.y));
    float shine = star*light.y*0.8*step(0.8,deform.z);
    vec3 rgb = mix(texel.rgb, vec3(0.93,1.0,1.0), shine);
    color = vec4(rgb*alpha, alpha);
}

blur:
#version 300 es
precision highp float;
uniform sampler2D image;
uniform vec2 direction;
in vec2 uv;
out vec4 color;
void main() {
    float a = texture(image,uv).a * 0.227027;
    a += texture(image,uv+direction*1.384615).a * 0.316216;
    a += texture(image,uv-direction*1.384615).a * 0.316216;
    a += texture(image,uv+direction*3.230769).a * 0.070270;
    a += texture(image,uv-direction*3.230769).a * 0.070270;
    color = vec4(a);
}
